UPDATE users
profile_image = #{profileImage}, phone = #{phone}, zonecode = #{zonecode}, road_address = #{roadAddress}, detail_address = #{detailAddress}, modified_at = #{modifiedAt}, modified_by = #{modifiedBy},
WHERE user_id = #{userId}

mapper.select:
SELECT COUNT(*)
FROM inquiry i


        i.created_by = #{userId}


        AND product_id = #{productId}


        AND is_answered = #{isAnswered}



            AND i.created_at >= #{startDate}




            AND i.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)


    AND i.upper_inquiry_id IS NULL

SELECT i.inquiry_id,
       i.product_id,
       i.title,
       i.content,
       i.is_secret,
       i.is_answered,
       i.created_at,
       u.username
FROM inquiry i LEFT JOIN users u ON u.user_id = i.created_by


        i.created_by = #{userId}


        AND product_id = #{productId}


        AND is_answered = #{isAnswered}



            AND i.created_at >= #{startDate}




            /* 종료일 당일의 전체 데이터를 포함하기 위해 1일을 더한 미만 조건 사용 */
            AND i.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)


    AND i.upper_inquiry_id is null

ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE inquiry
SET is_answered = 'Y'
WHERE inquiry_id = #{inquiryId}

mapper.select:
SELECT review_id, product_id, content, review_images, rating, r.created_by, r.created_at, u.email FROM review r LEFT JOIN users u ON u.user_id = r.created_by WHERE product_id = #{productId}
AND review_images IS NOT NULL AND JSON_LENGTH(review_images) > 0
ORDER BY rating DESC, created_at DESC
ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}
